"use client";

import { interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import {
  defaultThickness,
  strikethroughPhases,
} from "@/registry/snap-cn/text-highlight";

export type ProblemStackResolveStyle = "strike" | "sweep";
export type ProblemStackTheme = "light" | "dark";

export interface ProblemStackProps {
  /** Pain points, one per beat — array of lines, or a single comma-separated string. */
  pains?: string[] | string;
  /** Frames between consecutive pain entrances. */
  beatFrames?: number;
  /** Frame when resolution begins. Defaults to `pains.length * beatFrames + 20`. */
  resolveAt?: number;
  /** `strike` draws a line through each pain; `sweep` slides them away. */
  resolveStyle?: ProblemStackResolveStyle;
  /** Line drawn/rising in the accent color after the pains resolve. */
  resolutionText?: string;
  /** Color of the resolution text (and sweep tint). */
  accentColor?: string;
  /** Strike line color. #F04438 (danger) or #667085 (muted) fit the system. */
  strikeColor?: string;
  /** Light (#101828 text) or dark (#FAFAFA text) palette. */
  theme?: ProblemStackTheme;
  /** Pain line size in pixels. The resolution line scales with it. */
  fontSize?: number;
  /** Global playback multiplier. */
  speed?: number;
  className?: string;
}

const FONT_FAMILY =
  'Inter, var(--font-geist-sans), -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';

/** Per-theme snap-cn palette for the stack. */
export const PROBLEM_STACK_PALETTES: Record<
  ProblemStackTheme,
  { text: string; muted: string }
> = {
  light: { text: "#101828", muted: "#667085" },
  dark: { text: "#FAFAFA", muted: "#A1A1AA" },
};

/** Frames each strike takes to draw across its line. */
export const STRIKE_DRAW_FRAMES = 12;

/** Frames between consecutive pain resolutions (strike or sweep). */
export const RESOLVE_STAGGER = 10;

/** Frames a sweep takes to slide a line out and collapse its row. */
export const SWEEP_FRAMES = 18;

/** Accepts an array or a comma-separated string; trims and drops empties. */
export function normalizePains(pains: string[] | string): string[] {
  const list = Array.isArray(pains) ? pains : pains.split(",");
  return list.map((p) => p.trim()).filter((p) => p.length > 0);
}

/** Frame at which pain `index` begins its entrance. */
export function painEnterFrame(index: number, beatFrames: number): number {
  return index * beatFrames;
}

/** Default resolution start: one beat-ish pause after the last pain lands. */
export function defaultResolveAt(count: number, beatFrames: number): number {
  return count * beatFrames + 20;
}

/** Frame at which pain `index` starts being struck / swept. */
export function resolveStartFrame(index: number, resolveAt: number): number {
  return resolveAt + index * RESOLVE_STAGGER;
}

/**
 * Frame at which the resolution line enters: once the last pain's
 * strike/sweep has finished.
 */
export function resolutionEnterFrame(
  count: number,
  resolveAt: number,
  resolveStyle: ProblemStackResolveStyle,
): number {
  if (count === 0) return resolveAt;
  const lastStart = resolveStartFrame(count - 1, resolveAt);
  return (
    lastStart + (resolveStyle === "strike" ? STRIKE_DRAW_FRAMES : SWEEP_FRAMES)
  );
}

export function ProblemStack({
  pains = "Chasing receipts, Copy-pasting into sheets, Month-end panic",
  beatFrames = 25,
  resolveAt,
  resolveStyle = "strike",
  resolutionText = "Acme does it for you",
  accentColor = "#266DF0",
  strikeColor = "#F04438",
  theme = "light",
  fontSize = 40,
  speed = 1,
  className,
}: ProblemStackProps) {
  const frame = useCurrentFrame() * speed;
  const { fps } = useVideoConfig();

  const palette = PROBLEM_STACK_PALETTES[theme] ?? PROBLEM_STACK_PALETTES.light;
  const lines = normalizePains(pains);
  const resolveStart = resolveAt ?? defaultResolveAt(lines.length, beatFrames);
  const resolutionAt = resolutionEnterFrame(
    lines.length,
    resolveStart,
    resolveStyle,
  );

  const lineThickness = defaultThickness(fontSize);
  const rowHeight = Math.round(fontSize * 1.3);
  const rowGap = Math.round(fontSize * 0.55);

  // High-damping spring: fast settle, no bounce (snap-cn chrome rule).
  const rise = (start: number) =>
    spring({
      frame: frame - start,
      fps,
      config: { damping: 200, stiffness: 170, mass: 0.8 },
      durationInFrames: 22,
    });

  const fadeIn = (start: number) =>
    interpolate(frame, [start, start + 8], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

  const resolutionProgress = rise(resolutionAt);

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "flex-start",
        padding: "0 10%",
        fontFamily: FONT_FAMILY,
      }}
    >
      {lines.map((line, i) => {
        const enterAt = painEnterFrame(i, beatFrames);
        const enter = rise(enterAt);
        const struckAt = resolveStartFrame(i, resolveStart);

        // Shared strikethrough timeline from text-highlight: line draws
        // 0–40% of the window, text settles right after.
        const phases = strikethroughPhases(struckAt, STRIKE_DRAW_FRAMES);
        const strikeWidth = interpolate(
          frame,
          [phases.drawStart, phases.drawEnd],
          [0, 100],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
        );
        const struckDim = interpolate(
          frame,
          [phases.fadeStart, phases.fadeEnd],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
        );

        const sweep = interpolate(
          frame,
          [struckAt, struckAt + SWEEP_FRAMES],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
        );

        const swept = resolveStyle === "sweep";
        const enterOpacity = fadeIn(enterAt);
        const opacity = swept
          ? enterOpacity * (1 - sweep)
          : enterOpacity * (1 - struckDim * 0.55);
        const translateX = swept ? sweep * -Math.round(fontSize * 1.5) : 0;

        return (
          <div
            // biome-ignore lint/suspicious/noArrayIndexKey: pains are positional and never reorder
            key={`${line}-${i}`}
            style={{
              // Sweep collapses the row so the resolution line rises up.
              height: swept ? rowHeight * (1 - sweep) : rowHeight,
              marginBottom: swept ? rowGap * (1 - sweep) : rowGap,
              display: "flex",
              alignItems: "center",
              overflow: "visible",
            }}
          >
            <span
              style={{
                position: "relative",
                display: "inline-block",
                fontSize,
                fontWeight: 600,
                letterSpacing: "-0.01em",
                lineHeight: 1.25,
                color: palette.text,
                whiteSpace: "pre",
                opacity,
                transform: `translateY(${(1 - enter) * 14}px) translateX(${translateX}px)`,
              }}
            >
              {line}
              {resolveStyle === "strike" ? (
                <span
                  aria-hidden
                  style={{
                    position: "absolute",
                    left: 0,
                    top: "50%",
                    height: lineThickness,
                    width: `${strikeWidth}%`,
                    background: strikeColor,
                    transform: "translateY(-50%)",
                    borderRadius: lineThickness / 2,
                  }}
                />
              ) : null}
            </span>
          </div>
        );
      })}

      {resolutionText ? (
        <div
          style={{
            fontSize: Math.round(fontSize * 1.15),
            fontWeight: 700,
            letterSpacing: "-0.02em",
            lineHeight: 1.2,
            color: accentColor,
            marginTop: Math.round(fontSize * 0.4),
            opacity: fadeIn(resolutionAt),
            transform: `translateY(${(1 - resolutionProgress) * 18}px)`,
          }}
        >
          {resolutionText}
        </div>
      ) : null}
    </div>
  );
}
